const esc = s => String(s ?? "").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const json = (x,s=200)=>new Response(JSON.stringify(x),{status:s,headers:{"content-type":"application/json"}});
const voteExpr = {
  P22:"v.p22_voted=1", G22:"v.g22_voted=1", P24:"v.p24_voted=1",
  G24:"v.g24_voted=1", P26:"v.p26_voted=1", G26:"v.g26_voted=1",
  None:"v.p22_voted=0 AND v.g22_voted=0 AND v.p24_voted=0 AND v.g24_voted=0 AND v.p26_voted=0 AND v.g26_voted=0"
};
function where(u, phone=false, email=false){
  const q=u.searchParams, w=[], b=[];
  if(q.get("street")){w.push("v.street=?");b.push(q.get("street"))}
  if(q.get("precinct")){w.push("v.precinct=?");b.push(q.get("precinct"))}
  if(q.get("voted") && voteExpr[q.get("voted")]) w.push(voteExpr[q.get("voted")]);
  if(q.get("method")){
    const e=q.get("voted")==="G26"?"g26":"p26";
    w.push(`v.${e}_method=?`);b.push(q.get("method"));
  }
  if(q.get("supporter")==="1") w.push("COALESCE(c.supporter,0)=1");
  if(q.get("parity")==="even") w.push("CAST(v.house_number AS INTEGER)%2=0");
  if(q.get("parity")==="odd") w.push("CAST(v.house_number AS INTEGER)%2=1");
  if(q.get("q")){
    const z="%"+q.get("q")+"%"; w.push("(v.first_name LIKE ? OR v.last_name LIKE ? OR v.household_address LIKE ? OR v.phone LIKE ? OR v.email LIKE ?)");
    b.push(z,z,z,z,z);
  }
  if(phone) w.push("v.phone IS NOT NULL AND TRIM(v.phone)<>'' AND COALESCE(c.bad_phone,0)=0");
  if(email) w.push("v.email IS NOT NULL AND TRIM(v.email)<>'' AND COALESCE(c.bad_email,0)=0");
  return {sql:w.length?" WHERE "+w.join(" AND "):"", binds:b};
}
const baseSelect = `SELECT v.*,COALESCE(c.knock_lit,0) knock_lit,COALESCE(c.talked,0) talked,
COALESCE(c.supporter,0) supporter,COALESCE(c.follow_up,0) follow_up,COALESCE(c.bad_phone,0) bad_phone,COALESCE(c.bad_email,0) bad_email,
COALESCE(c.do_not_contact,0) do_not_contact,COALESCE(c.intends_mail,0) intends_mail,
COALESCE(c.intends_early,0) intends_early,COALESCE(c.intends_polls,0) intends_polls,COALESCE(c.intends_no_vote,0) intends_no_vote,COALESCE(c.mail_help,0) mail_help,COALESCE(c.mail_pickup,0) mail_pickup,COALESCE(c.early_ride,0) early_ride,COALESCE(c.vol_canvass,0) vol_canvass,COALESCE(c.vol_phone,0) vol_phone,COALESCE(c.vol_host,0) vol_host,COALESCE(c.vol_polls,0) vol_polls,c.notes campaign_notes,(SELECT MAX(created_at) FROM activity_log al WHERE al.voter_id=v.voter_id AND al.action_type='CALL') last_call_at,(SELECT MAX(created_at) FROM activity_log al WHERE al.voter_id=v.voter_id AND al.action_type='TEXT') last_text_at,(SELECT MAX(created_at) FROM activity_log al WHERE al.voter_id=v.voter_id AND al.action_type='EMAIL') last_email_at
FROM voters v LEFT JOIN campaign_activity c ON c.voter_id=v.voter_id`;


async function sha256(s){const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("")}
function cookie(req,name){const m=(req.headers.get("cookie")||"").match(new RegExp("(?:^|; )"+name+"=([^;]*)"));return m?decodeURIComponent(m[1]):""}
async function currentUser(req,env){const t=cookie(req,"gg_session");if(!t)return null;return await env.DB.prepare("SELECT u.id,u.name,u.role FROM app_sessions s JOIN app_users u ON u.id=s.user_id WHERE s.token=? AND u.active=1 AND s.expires_at>CURRENT_TIMESTAMP").bind(t).first()}
function xmlEsc(s){return String(s??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;")}
function excelXml(rows){const cols=rows.length?Object.keys(rows[0]):[];let x='<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Report"><Table>';x+='<Row>'+cols.map(c=>'<Cell><Data ss:Type="String">'+xmlEsc(c)+'</Data></Cell>').join("")+'</Row>';for(const r of rows)x+='<Row>'+cols.map(c=>'<Cell><Data ss:Type="String">'+xmlEsc(r[c])+'</Data></Cell>').join("")+'</Row>';return x+'</Table></Worksheet></Workbook>'}

async function api(req,env,u){
  const p=u.pathname;
  if(p==="/api/login"&&req.method==="POST"){const d=await req.json();const user=await env.DB.prepare("SELECT * FROM app_users WHERE name=? COLLATE NOCASE AND active=1").bind(String(d.name||"").trim()).first();if(!user||await sha256(user.pin_salt+":"+String(d.pin||""))!==user.pin_hash)return json({error:"Invalid name or PIN"},401);const token=crypto.randomUUID()+crypto.randomUUID();await env.DB.prepare("INSERT INTO app_sessions(token,user_id,expires_at) VALUES(?,?,datetime('now','+30 days'))").bind(token,user.id).run();return new Response(JSON.stringify({ok:true,name:user.name,role:user.role}),{headers:{"content-type":"application/json","set-cookie":"gg_session="+encodeURIComponent(token)+"; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=2592000"}})}
  if(p==="/api/logout"&&req.method==="POST"){const t=cookie(req,"gg_session");if(t)await env.DB.prepare("DELETE FROM app_sessions WHERE token=?").bind(t).run();return new Response(JSON.stringify({ok:true}),{headers:{"content-type":"application/json","set-cookie":"gg_session=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0"}})}
  const user=await currentUser(req,env);if(!user)return json({error:"login required"},401);
  if(p==="/api/me")return json(user);
  if(p.startsWith("/api/admin/")){if(user.role!=="owner")return json({error:"admin only"},403);
    if(p==="/api/admin/users"&&req.method==="GET")return json((await env.DB.prepare("SELECT id,name,role,active,created_at,updated_at FROM app_users ORDER BY active DESC,name").all()).results);
    if(p==="/api/admin/users"&&req.method==="POST"){const d=await req.json(),name=String(d.name||"").trim(),pin=String(d.pin||"").trim();if(!name||!/^[0-9]{4,8}$/.test(pin))return json({error:"Name and 4–8 digit PIN required"},400);const salt=crypto.randomUUID(),hash=await sha256(salt+":"+pin);try{await env.DB.prepare("INSERT INTO app_users(name,pin_salt,pin_hash,role,active) VALUES(?,?,?,'user',1)").bind(name,salt,hash).run()}catch(e){return json({error:"That name already exists"},400)}await env.DB.prepare("INSERT INTO admin_audit(actor_user_id,action,detail) VALUES(?,'ADD_USER',?)").bind(user.id,name).run();return json({ok:true})}
    if(p==="/api/admin/users"&&req.method==="PATCH"){const d=await req.json();if(!d.id)return json({error:"missing user"},400);if(d.pin){if(!/^[0-9]{4,8}$/.test(String(d.pin)))return json({error:"PIN must be 4–8 digits"},400);const salt=crypto.randomUUID(),hash=await sha256(salt+":"+String(d.pin));await env.DB.prepare("UPDATE app_users SET pin_salt=?,pin_hash=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(salt,hash,d.id).run()}if(typeof d.active==="boolean"){if(Number(d.id)===Number(user.id)&&!d.active)return json({error:"You cannot deactivate your own owner account"},400);await env.DB.prepare("UPDATE app_users SET active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(d.active?1:0,d.id).run()}await env.DB.prepare("INSERT INTO admin_audit(actor_user_id,action,detail) VALUES(?,'UPDATE_USER',?)").bind(user.id,String(d.id)).run();return json({ok:true})}
    if(p==="/api/admin/export"){const type=u.searchParams.get("type")||"backup";let q;if(type==="supporters")q="SELECT v.voter_id,v.first_name,v.last_name,v.house_number,v.street,v.unit,v.phone,v.email,c.supporter,c.intends_early,c.intends_mail,c.intends_polls,c.notes FROM voters v JOIN campaign_activity c ON c.voter_id=v.voter_id WHERE c.supporter=1 ORDER BY v.street,CAST(v.house_number AS INTEGER),v.last_name";else if(type==="canvass")q="SELECT v.voter_id,v.first_name,v.last_name,v.house_number,v.street,v.unit,c.knock_lit,c.talked,c.follow_up,c.supporter,c.notes,c.updated_at FROM voters v LEFT JOIN campaign_activity c ON c.voter_id=v.voter_id WHERE c.voter_id IS NOT NULL ORDER BY v.street,CAST(v.house_number AS INTEGER),v.last_name";else if(type==="outreach")q="SELECT al.id,al.voter_id,v.first_name,v.last_name,v.phone,v.email,al.action_type,al.action_value,al.note,al.created_at,al.created_by FROM activity_log al LEFT JOIN voters v ON v.voter_id=al.voter_id WHERE al.action_type IN ('TEXT','CALL','EMAIL') ORDER BY al.created_at DESC";else if(type==="intentions")q="SELECT v.voter_id,v.first_name,v.last_name,v.house_number,v.street,v.unit,c.supporter,c.intends_early,c.intends_mail,c.intends_polls,c.intends_no_vote FROM voters v JOIN campaign_activity c ON c.voter_id=v.voter_id WHERE c.intends_early=1 OR c.intends_mail=1 OR c.intends_polls=1 OR c.intends_no_vote=1 ORDER BY v.street,CAST(v.house_number AS INTEGER),v.last_name";else if(type==="audit")q="SELECT a.id,u.name actor,a.action,a.detail,a.created_at FROM admin_audit a LEFT JOIN app_users u ON u.id=a.actor_user_id ORDER BY a.created_at DESC";else q="SELECT v.*,c.knock_lit,c.talked,c.supporter,c.follow_up,c.bad_phone,c.bad_email,c.intends_mail,c.intends_early,c.intends_polls,c.intends_no_vote,c.notes campaign_notes,c.updated_at campaign_updated_at FROM voters v LEFT JOIN campaign_activity c ON c.voter_id=v.voter_id ORDER BY v.street,CAST(v.house_number AS INTEGER),v.unit,v.last_name";const rows=(await env.DB.prepare(q).all()).results;await env.DB.prepare("INSERT INTO admin_audit(actor_user_id,action,detail) VALUES(?,'EXPORT',?)").bind(user.id,type).run();return new Response(excelXml(rows),{headers:{"content-type":"application/vnd.ms-excel; charset=utf-8","content-disposition":'attachment; filename="ward10-'+type+'-'+new Date().toISOString().slice(0,10)+'.xls"',"cache-control":"no-store"}})}
  }
  if(p==="/api/calendar" && req.method==="GET"){const rows=(await env.DB.prepare("SELECT e.*,EXISTS(SELECT 1 FROM calendar_signups cs WHERE cs.event_id=e.id AND cs.user_id=?) signed_up,(SELECT GROUP_CONCAT(au.name, ', ') FROM calendar_signups cs JOIN app_users au ON au.id=cs.user_id WHERE cs.event_id=e.id) signup_names,(SELECT GROUP_CONCAT(cg.name, ', ') FROM calendar_guests cg WHERE cg.event_id=e.id) guest_names FROM calendar_events e WHERE e.event_date>='2026-10-04' ORDER BY e.event_date,e.start_time,e.id").bind(user.id).all()).results;return json(rows)}
  if(p==="/api/calendar/event" && req.method==="POST"){const d=await req.json();if(!d.event_date||!d.title)return json({error:"date and title required"},400);const r=await env.DB.prepare("INSERT INTO calendar_events(event_date,title,event_type,start_time,end_time,notes) VALUES(?,?,?,?,?,?)").bind(d.event_date,String(d.title),String(d.event_type||"event"),d.start_time||null,d.end_time||null,String(d.notes||"")).run();return json({ok:true,id:r.meta?.last_row_id})}
  if(p==="/api/calendar/event" && req.method==="PATCH"){const d=await req.json();if(!d.id||!d.event_date||!d.title)return json({error:"bad request"},400);await env.DB.prepare("UPDATE calendar_events SET event_date=?,title=?,event_type=?,start_time=?,end_time=?,notes=? WHERE id=?").bind(d.event_date,String(d.title),String(d.event_type||"event"),d.start_time||null,d.end_time||null,String(d.notes||""),d.id).run();return json({ok:true})}
  if(p==="/api/calendar/event" && req.method==="DELETE"){const d=await req.json();if(!d.id)return json({error:"bad request"},400);await env.DB.prepare("DELETE FROM calendar_signups WHERE event_id=?").bind(d.id).run();await env.DB.prepare("DELETE FROM calendar_events WHERE id=?").bind(d.id).run();return json({ok:true})}
  if(p==="/api/calendar/signup" && req.method==="POST"){const d=await req.json();if(!d.event_id)return json({error:"bad request"},400);if(d.join)await env.DB.prepare("INSERT OR IGNORE INTO calendar_signups(event_id,user_id) VALUES(?,?)").bind(d.event_id,user.id).run();else await env.DB.prepare("DELETE FROM calendar_signups WHERE event_id=? AND user_id=?").bind(d.event_id,user.id).run();return json({ok:true})}
  if(p==="/api/calendar/guest" && req.method==="POST"){const d=await req.json();if(!d.event_id||!String(d.name||"").trim())return json({error:"event and name required"},400);await env.DB.prepare("INSERT INTO calendar_guests(event_id,name,created_by) VALUES(?,?,?)").bind(d.event_id,String(d.name).trim(),user.id).run();return json({ok:true})}
  if(p==="/api/calendar/guest" && req.method==="DELETE"){const d=await req.json();if(!d.id)return json({error:"bad request"},400);await env.DB.prepare("DELETE FROM calendar_guests WHERE id=?").bind(d.id).run();return json({ok:true})}
  if(p==="/api/calendar/notes" && req.method==="POST"){const d=await req.json();if(!d.event_id)return json({error:"bad request"},400);await env.DB.prepare("UPDATE calendar_events SET notes=? WHERE id=?").bind(String(d.notes||""),d.event_id).run();return json({ok:true})}
  if(p==="/api/meta"){
    const [streets,precincts]=await Promise.all([
      env.DB.prepare("SELECT DISTINCT street FROM voters ORDER BY street").all(),
      env.DB.prepare("SELECT precinct,COUNT(*) count FROM voters GROUP BY precinct ORDER BY precinct").all()
    ]);
    return json({streets:streets.results.map(x=>x.street),precincts:precincts.results});
  }
  if(p==="/api/voters"){
    const mode=u.searchParams.get("mode")||"canvass", x=where(u,mode==="text",mode==="email");
    const desc=u.searchParams.get("dir")==="desc"?"DESC":"ASC";
    const order=mode==="canvass"?` ORDER BY CAST(v.house_number AS INTEGER) ${desc},v.house_number ${desc},v.unit,v.last_name,v.first_name`:" ORDER BY v.street,CAST(v.house_number AS INTEGER),v.unit,v.last_name";
    const st=env.DB.prepare(baseSelect+x.sql+order+" LIMIT 1000").bind(...x.binds);
    const data=await st.all();
    return json(data.results);
  }
  if(p==="/api/summary"){
    const sm=u.searchParams.get("mode"); const x=where(u,sm==="text",sm==="email");
    const sql=sm==="text"?`SELECT COUNT(*) phone_count FROM voters v LEFT JOIN campaign_activity c ON c.voter_id=v.voter_id${x.sql}`:sm==="email"?`SELECT COUNT(*) email_count FROM voters v LEFT JOIN campaign_activity c ON c.voter_id=v.voter_id${x.sql}`:`SELECT
      COUNT(*) total_voters,
      SUM(CASE WHEN v.p26_voted=1 THEN 1 ELSE 0 END) primary_voters,
      COUNT(DISTINCT v.house_number||'|'||v.street||'|'||COALESCE(v.unit,'')) total_doors,
      COUNT(DISTINCT v.house_number||'|'||v.street) total_houses
      FROM voters v LEFT JOIN campaign_activity c ON c.voter_id=v.voter_id${x.sql}`;
    return json(await env.DB.prepare(sql).bind(...x.binds).first());
  }
  if(p==="/api/stats"){
    const overall=await env.DB.prepare(`SELECT COUNT(*) total_voters,
      SUM(COALESCE(c.supporter,0)) supporters,
      SUM(CASE WHEN COALESCE(c.supporter,0)=1 AND COALESCE(c.intends_early,0)=1 THEN 1 ELSE 0 END) supporter_early,
      SUM(CASE WHEN COALESCE(c.supporter,0)=1 AND COALESCE(c.intends_mail,0)=1 THEN 1 ELSE 0 END) supporter_mail,
      SUM(CASE WHEN COALESCE(c.supporter,0)=1 AND COALESCE(c.intends_polls,0)=1 THEN 1 ELSE 0 END) supporter_polls,
      SUM(COALESCE(c.talked,0)) talked,
      SUM(CASE WHEN COALESCE(c.knock_lit,0)=1 OR COALESCE(c.talked,0)=1 OR COALESCE(c.supporter,0)=1 OR COALESCE(c.follow_up,0)=1 OR EXISTS(SELECT 1 FROM activity_log al WHERE al.voter_id=v.voter_id AND al.action_type IN ('CALL','TEXT','EMAIL')) THEN 1 ELSE 0 END) voters_reached,
      COUNT(DISTINCT CASE WHEN COALESCE(c.knock_lit,0)=1 THEN v.house_number||'|'||v.street||'|'||COALESCE(v.unit,'') END) doors_knocked,
      COUNT(DISTINCT CASE WHEN COALESCE(c.knock_lit,0)=1 THEN v.house_number||'|'||v.street END) houses_knocked,\n      COUNT(DISTINCT v.house_number||'|'||v.street||'|'||COALESCE(v.unit,'')) total_doors,\n      COUNT(DISTINCT v.house_number||'|'||v.street) total_houses\n      FROM voters v LEFT JOIN campaign_activity c ON c.voter_id=v.voter_id`).first();
    const outreach=await env.DB.prepare(`SELECT
      SUM(CASE WHEN action_type='TEXT' THEN 1 ELSE 0 END) texts,
      SUM(CASE WHEN action_type='CALL' THEN 1 ELSE 0 END) calls,
      SUM(CASE WHEN action_type='EMAIL' THEN 1 ELSE 0 END) emails,
      COUNT(DISTINCT CASE WHEN action_type IN ('TEXT','CALL','EMAIL') THEN voter_id END) unique_contacts
      FROM activity_log`).first();
    const my=await env.DB.prepare("SELECT COUNT(DISTINCT CASE WHEN al.action_type='TALKED' AND al.action_value='1' THEN al.voter_id END) my_talked,COUNT(DISTINCT CASE WHEN al.action_type IN ('KNOCK_LIT','TALKED','SUPPORTER','FOLLOW_UP','CALL','TEXT','EMAIL') THEN al.voter_id END) my_voters_reached,COUNT(DISTINCT CASE WHEN al.action_type='KNOCK_LIT' AND al.action_value='1' THEN v.house_number||'|'||v.street||'|'||COALESCE(v.unit,'') END) my_doors_knocked,COUNT(DISTINCT CASE WHEN al.action_type='KNOCK_LIT' AND al.action_value='1' THEN v.house_number||'|'||v.street END) my_houses_knocked,SUM(CASE WHEN al.action_type='TEXT' THEN 1 ELSE 0 END) my_texts,SUM(CASE WHEN al.action_type='CALL' THEN 1 ELSE 0 END) my_calls,SUM(CASE WHEN al.action_type='EMAIL' THEN 1 ELSE 0 END) my_emails,COUNT(DISTINCT CASE WHEN al.action_type IN ('TEXT','CALL','EMAIL') THEN al.voter_id END) my_unique_contacts FROM activity_log al LEFT JOIN voters v ON v.voter_id=al.voter_id WHERE al.created_by=?").bind(String(user.id)).first();
    return json({...overall,...outreach,...my});
  }
  if(p==="/api/field-plan"){
    const x=where(u), sort={complete:"percent_complete",reached:"reached_percent",primary:"primary_voters",all:"all_voters",none:"none_voters"}[u.searchParams.get("sort")]||"street";
    const dir=u.searchParams.get("dir")==="desc"?"DESC":"ASC";
    const sql=`SELECT v.street,COUNT(*) all_voters,SUM(v.p26_voted) primary_voters,
      SUM(CASE WHEN v.p22_voted=0 AND v.g22_voted=0 AND v.p24_voted=0 AND v.g24_voted=0 AND v.p26_voted=0 AND v.g26_voted=0 THEN 1 ELSE 0 END) none_voters,
      COUNT(DISTINCT v.house_number) total_houses,
      SUM(COALESCE(c.supporter,0)) supporters, COUNT(DISTINCT v.house_number||'|'||COALESCE(v.unit,'')) total_doors,
      SUM(COALESCE(c.knock_lit,0)) completed,
      COUNT(DISTINCT CASE WHEN COALESCE(c.knock_lit,0)=1 THEN v.house_number END) houses_knocked,
      SUM(CASE WHEN COALESCE(c.knock_lit,0)=1 OR COALESCE(c.talked,0)=1 OR COALESCE(c.supporter,0)=1 OR COALESCE(c.follow_up,0)=1 OR EXISTS(SELECT 1 FROM activity_log al WHERE al.voter_id=v.voter_id AND al.action_type IN ('CALL','TEXT','EMAIL')) THEN 1 ELSE 0 END) voters_reached,
      ROUND(100.0*COUNT(DISTINCT CASE WHEN COALESCE(c.knock_lit,0)=1 THEN v.house_number END)/NULLIF(COUNT(DISTINCT v.house_number),0),1) percent_complete,
      ROUND(100.0*SUM(CASE WHEN COALESCE(c.knock_lit,0)=1 OR COALESCE(c.talked,0)=1 OR COALESCE(c.supporter,0)=1 OR COALESCE(c.follow_up,0)=1 OR EXISTS(SELECT 1 FROM activity_log al WHERE al.voter_id=v.voter_id AND al.action_type IN ('CALL','TEXT','EMAIL')) THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),1) reached_percent,
      GROUP_CONCAT(DISTINCT v.precinct) precincts
      FROM voters v LEFT JOIN campaign_activity c ON c.voter_id=v.voter_id${x.sql} GROUP BY v.street ORDER BY ${sort} ${dir}`;
    return json((await env.DB.prepare(sql).bind(...x.binds).all()).results);
  }
  if(p==="/api/activity" && req.method==="POST"){
    const d=await req.json(), allowed=["knock_lit","talked","supporter","follow_up","bad_phone","bad_email","do_not_contact","intends_mail","intends_early","intends_polls","intends_no_vote","mail_help","mail_pickup","early_ride","vol_canvass","vol_phone","vol_host","vol_polls","notes"];
    if(!d.voter_id || !allowed.includes(d.field)) return json({error:"bad request"},400);
    const value=d.field==="notes"?String(d.value??""):(d.value?1:0);if(value&&["intends_mail","intends_early","intends_polls","intends_no_vote"].includes(d.field))await env.DB.prepare("INSERT INTO campaign_activity(voter_id,updated_at) VALUES(?,CURRENT_TIMESTAMP) ON CONFLICT(voter_id) DO UPDATE SET intends_mail=0,intends_early=0,intends_polls=0,intends_no_vote=0,updated_at=CURRENT_TIMESTAMP").bind(d.voter_id).run();
    await env.DB.prepare(`INSERT INTO campaign_activity(voter_id,${d.field},updated_at) VALUES(?,?,CURRENT_TIMESTAMP)
      ON CONFLICT(voter_id) DO UPDATE SET ${d.field}=excluded.${d.field},updated_at=CURRENT_TIMESTAMP`).bind(d.voter_id,value).run();
    await env.DB.prepare("INSERT INTO activity_log(voter_id,action_type,action_value,created_by) VALUES(?,?,?,?)").bind(d.voter_id,d.field.toUpperCase(),String(value),String(user.id)).run();
    return json({ok:true});
  }
  if(p==="/api/contact" && req.method==="POST"){const d=await req.json();if(!d.voter_id||!["CALL","TEXT","EMAIL"].includes(d.type))return json({error:"bad request"},400);await env.DB.prepare("INSERT INTO activity_log(voter_id,action_type,action_value,note,created_by) VALUES(?,?,?,?,?)").bind(d.voter_id,d.type,d.provider||"phone",(d.type==="TEXT"||d.type==="EMAIL")?(d.message||""):null,String(user.id)).run();return json({ok:true})}
  if(p==="/api/contact" && req.method==="PATCH"){const d=await req.json();if(!d.id||!d.voter_id||!["CALL","TEXT"].includes(d.type)||!/^\\d{4}-\\d{2}-\\d{2}$/.test(d.date||""))return json({error:"bad request"},400);await env.DB.prepare("UPDATE activity_log SET action_type=?,created_at=? WHERE id=? AND voter_id=? AND action_type IN ('CALL','TEXT')").bind(d.type,d.date+" 12:00:00",d.id,d.voter_id).run();return json({ok:true})}
  if(p==="/api/contact" && req.method==="DELETE"){const d=await req.json();await env.DB.prepare("DELETE FROM activity_log WHERE id=? AND voter_id=? AND action_type IN ('CALL','TEXT')").bind(d.id,d.voter_id).run();return json({ok:true})}
  if(p==="/api/contact-history"){const id=u.searchParams.get("voter_id");return json((await env.DB.prepare("SELECT id,action_type,action_value,note,created_at FROM activity_log WHERE voter_id=? AND action_type IN ('CALL','TEXT') ORDER BY created_at DESC,id DESC").bind(id).all()).results)}
  return json({error:"not found"},404);
}
