async function adminPage(){let users=await getJSON("/api/admin/users");$("#summary").innerHTML="";$("#content").innerHTML='<div class="adminPage"><h2>Admin</h2><section><h3>TEAM ACCESS</h3><div class="adminAdd"><input id="newUserName" placeholder="Name"><input id="newUserPin" placeholder="4–8 digit PIN" inputmode="numeric" type="password"><button id="addUserBtn">Add Person</button></div><div id="userList">'+users.map(u=>'<div class="userRow"><b>'+esc(u.name)+'</b><span>'+esc(u.role)+(u.active?" · Active":" · Inactive")+'</span><button data-userpin="'+u.id+'">Change PIN</button>'+(u.role==="owner"?"":'<button data-useractive="'+u.id+'" data-active="'+(u.active?0:1)+'">'+(u.active?"Remove Access":"Restore")+'</button>')+'</div>').join("")+'</div></section><section><h3>EXCEL EXPORTS</h3><div class="exportGrid"><a href="/api/admin/export?type=backup">Full Campaign Backup</a><a href="/api/admin/export?type=supporters">Supporters</a><a href="/api/admin/export?type=canvass">Canvassing Activity</a><a href="/api/admin/export?type=outreach">Text / Call / Email</a><a href="/api/admin/export?type=intentions">Voting Intentions</a><a href="/api/admin/export?type=audit">Activity Log</a></div></section><button id="logoutBtn">Sign Out</button></div>';$("#addUserBtn").onclick=addUser;$("#logoutBtn").onclick=logout;document.querySelectorAll("[data-useractive]").forEach(b=>b.onclick=()=>setUserActive(b));document.querySelectorAll("[data-userpin]").forEach(b=>b.onclick=()=>changeUserPin(b))}
async function addUser(){let name=$("#newUserName").value.trim(),pin=$("#newUserPin").value.trim();let r=await fetch("/api/admin/users",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name,pin})}),z=await r.json();if(!r.ok)return alert(z.error||"Could not add person");adminPage()}
async function setUserActive(b){let r=await fetch("/api/admin/users",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id:Number(b.dataset.useractive),active:b.dataset.active==="1"})}),z=await r.json();if(!r.ok)return alert(z.error||"Could not update access");adminPage()}
async function changeUserPin(b){let pin=prompt("Enter new 4–8 digit PIN");if(pin===null)return;let r=await fetch("/api/admin/users",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({id:Number(b.dataset.userpin),pin})}),z=await r.json();if(!r.ok)return alert(z.error||"Could not change PIN");alert("PIN updated")}
async function logout(){await fetch("/api/logout",{method:"POST"});location.reload()}
async function field(p){let sort=window.fieldSortKey||"primary",dir=window.fieldSortDir||"desc";let fp=new URLSearchParams({sort,dir});if($("#precinct").value)fp.set("precinct",$("#precinct").value);let rows=await getJSON("/api/field-plan?"+fp);$("#summary").innerHTML="";let ranked=rows.slice().sort((a,b)=>Number(b.all_voters)-Number(a.all_voters)),doorSum=0,goalNames=new Set(),goalVoters=0;for(const x of ranked){if(doorSum>=2000)break;goalNames.add(x.street);doorSum+=Number(x.total_doors||0);goalVoters+=Number(x.all_voters||0)}let goalPct=Math.min(100,100*doorSum/2000).toFixed(1);$("#content").innerHTML='<div class="fieldPage"><div class="fieldSortBar"><button data-fieldkey="street">Street '+(sort==="street"&&dir==="desc"?"Z→A":"A→Z")+'</button><button data-fieldkey="primary">Primary '+(sort==="primary"&&dir==="asc"?"↑":"↓")+'</button><button data-fieldkey="all">Voters '+(sort==="all"&&dir==="asc"?"↑":"↓")+'</button><button data-fieldkey="complete">Houses % '+(sort==="complete"&&dir==="asc"?"↑":"↓")+'</button><button data-fieldkey="reached">Reached % '+(sort==="reached"&&dir==="asc"?"↑":"↓")+'</button></div><div class="fieldPrecinctBar"><b>PRECINCT</b><button class="fieldPrecinct" data-pct="">All</button><button class="fieldPrecinct" data-pct="2827">2827</button><button class="fieldPrecinct" data-pct="2828">2828</button><button class="fieldPrecinct" data-pct="2832">2832</button><button class="fieldPrecinct" data-pct="2833">2833</button></div><div class="fieldGoal"><b>TOP '+goalNames.size+' STREETS · '+goalVoters.toLocaleString()+' VOTERS</b><span>'+doorSum.toLocaleString()+' DOORS · GOAL 2,000</span></div>'+rows.map(x=>'<div class="row street '+(goalNames.has(x.street)?"top20":"")+'" data-open-street="'+esc(x.street)+'" style="--complete:'+Math.max(0,Math.min(100,Number(x.percent_complete||0)))+'%"><b>'+esc(x.street) +'</b><span>'+x.primary_voters+' Primary</span><span>'+x.all_voters+' voters</span><span>'+x.total_doors+' doors</span><span>'+x.percent_complete+'% houses</span><span>'+x.reached_percent+'% reached</span></div>').join("")+'</div>';document.querySelectorAll("[data-fieldkey]").forEach(b=>b.classList.toggle("selected",b.dataset.fieldkey===sort));document.querySelectorAll(".fieldPrecinct").forEach(b=>b.classList.toggle("selected",b.dataset.pct===$("#precinct").value));document.querySelectorAll(".fieldPrecinct").forEach(b=>b.onclick=async()=>{$("#precinct").value=b.dataset.pct;await field(new URLSearchParams())})}
async function setFieldSort(b){let key=b.dataset.fieldkey,def=key==="street"?"asc":"desc";window.fieldSortDir=window.fieldSortKey===key?(window.fieldSortDir==="asc"?"desc":"asc"):def;window.fieldSortKey=key;await field(new URLSearchParams())}
function md(s){if(!s)return "";let d=new Date(String(s).replace(" ","T")+"Z");return isNaN(d)?String(s).slice(5,10):new Intl.DateTimeFormat("en-US",{month:"numeric",day:"numeric",timeZone:"America/New_York"}).format(d)}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function switchTab(next,el){document.querySelectorAll(".tabs button").forEach(x=>x.classList.remove("active"));el.classList.add("active");tab=next;document.body.classList.toggle("canvassTab",tab==="canvass");let hideMain=tab==="stats"||tab==="field"||tab==="supporters"||tab==="calendar"||tab==="campaign"||tab==="admin";document.querySelector(".filters").style.setProperty("display",hideMain?"none":"flex","important");document.querySelector(".searchRow").style.setProperty("display",hideMain?"none":"flex","important");$("#collapseFiltersBtn").style.display=(hideMain||tab==="field")?"none":"block";document.querySelector("#textTools").style.display=tab==="text"?"block":"none";document.querySelector("#emailTools").style.display=tab==="email"?"block":"none";document.querySelector(".canvassTools").style.setProperty("display",tab==="canvass"?"flex":"none","important");load()}
