document.querySelectorAll(".filterBtn").forEach(b=>b.addEventListener("click",()=>pickFilter(b)));
function updateEmailSelected(){let n=document.querySelectorAll(".emailSelect:checked").length;$("#emailSelectedCount").textContent=n+" selected"}function selectedEmails(){return [...document.querySelectorAll(".emailSelect:checked")].map(x=>x.dataset.email).filter(Boolean)}async function copyEmails(){let val=selectedEmails().join("; ");if(!val)return;try{await navigator.clipboard.writeText(val)}catch(e){let t=document.createElement("textarea");t.value=val;document.body.appendChild(t);t.select();document.execCommand("copy");t.remove()}$("#copySelectedEmails").textContent="Copied "+selectedEmails().length;setTimeout(()=>$("#copySelectedEmails").textContent="Copy Selected",1200)}$("#selectAllEmails").addEventListener("click",()=>{document.querySelectorAll(".emailSelect").forEach(x=>x.checked=true);updateEmailSelected()});$("#clearEmailSelection").addEventListener("click",()=>{document.querySelectorAll(".emailSelect").forEach(x=>x.checked=false);updateEmailSelected()});$("#copySelectedEmails").addEventListener("click",copyEmails);document.addEventListener("change",e=>{if(e.target.matches(".emailSelect"))updateEmailSelected()});$("#clearFiltersBtn").addEventListener("click",clearFilters);$("#clearMessage").addEventListener("click",()=>{$("#message").value=""});$("#clearEmailMessage").addEventListener("click",()=>{$("#emailMessage").value=""});
