window.houseDir="asc";window.parity="";window.expandDoors=false;$("#doorExpandBtn").textContent="Expand";$("#doorExpandBtn").addEventListener("click",()=>{window.expandDoors=!window.expandDoors;$("#doorExpandBtn").textContent=window.expandDoors?"Collapse":"Expand";load()});
document.querySelectorAll(".sortBtn").forEach(b=>b.addEventListener("click",()=>{window.houseDir=b.dataset.dir;document.querySelectorAll(".sortBtn").forEach(x=>x.classList.toggle("selected",x===b));load()}));
