$("#collapseFiltersBtn").addEventListener("click",()=>{let box=document.querySelector(".filters"),hidden=getComputedStyle(box).display==="none";box.style.setProperty("display",hidden?"flex":"none","important");$("#collapseFiltersBtn").textContent=hidden?"Hide Filters":"Show Filters"});let t;$("#search").addEventListener("input",()=>{clearTimeout(t);t=setTimeout(load,250)});
document.addEventListener("click",async e=>{let ls=e.target.closest("[data-listsort]");if(ls){let key=ls.dataset.listsort,cur=window.listSort[tab]||["address","asc"],def=key==="primary"?"desc":"asc";window.listSort[tab]=[key,cur[0]===key?(cur[1]==="asc"?"desc":"asc"):def];await load();return}let st=e.target.closest('[data-action="supporter-toggle"]');if(st){let card=st.closest(".supporterCard"),open=card.classList.toggle("supportOpen");let ch=card.querySelector(".supportChevron");if(ch)ch.textContent=open?"▾":"▸";return}let ca=e.target.closest('[data-action="cal-add"]');if(ca){openCalModal(null);return}let cc=e.target.closest('[data-action="cal-close"]');if(cc){closeCalModal();return}let co=e.target.closest('[data-action="cal-open"]');if(co){openCalModal(co.closest(".calEvent"));return}let cga=e.target.closest('[data-action="cal-guest-add"]');if(cga){let id=Number(cga.dataset.id),inp=document.querySelector('[data-guest-name="'+id+'"]'),name=inp?inp.value.trim():"";if(!name)return;let r=await fetch("/api/calendar/guest",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({event_id:id,name})});if(!r.ok){alert("Could not add person");return}await calendarPage();return}let csv=e.target.closest('[data-action="cal-save"]');if(csv){let id=$("#calId").value,d={id:id?Number(id):undefined,title:$("#calTitle").value,event_type:$("#calType").value,event_date:$("#calDate").value,start_time:$("#calStart").value,end_time:$("#calEnd").value,notes:$("#calEditNotes").value};let r=await fetch("/api/calendar/event",{method:id?"PATCH":"POST",headers:{"content-type":"application/json"},body:JSON.stringify(d)});if(!r.ok){alert("Could not save event");return}closeCalModal();await calendarPage();return}let cdel=e.target.closest('[data-action="cal-delete"]');if(cdel){let id=Number($("#calId").value);if(id&&confirm("Delete this event?")){await fetch("/api/calendar/event",{method:"DELETE",headers:{"content-type":"application/json"},body:JSON.stringify({id})});closeCalModal();await calendarPage()}return}let cms=e.target.closest('[data-action="cal-modal-sign"]');if(cms){let id=Number($("#calId").value);await fetch("/api/calendar/signup",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({event_id:id,join:cms.dataset.join==="1"})});closeCalModal();await calendarPage();return}let cp=e.target.closest('[data-action="cal-prev"]');if(cp){calMonth--;if(calMonth<0){calMonth=11;calYear--}await calendarPage();return}let cn=e.target.closest('[data-action="cal-next"]');if(cn){calMonth++;if(calMonth>11){calMonth=0;calYear++}await calendarPage();return}let cd=e.target.closest('[data-cal-date]');if(cd){document.querySelectorAll(".calEvent").forEach(x=>x.style.display=x.querySelector(".dateBadge")&&x.innerHTML.includes(String(Number(cd.dataset.calDate.slice(-2))))?"flex":"flex");return}let ct=e.target.closest('[data-action="cal-toggle"]');if(ct){ct.closest(".calCard").classList.toggle("calOpen");return}let cs=e.target.closest('[data-action="cal-sign"]');if(cs){await fetch("/api/calendar/signup",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({event_id:Number(cs.dataset.id),join:cs.dataset.join==="1"})});await calendarPage();return}let g=e.target.closest("[data-go]");if(g){if(g.dataset.go==="mailto"){await fetch("/api/contact",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({voter_id:g.dataset.voter,type:"EMAIL",provider:"email",message:$("#emailMessage").value||""})});let body=$("#emailMessage").value||"";location.href="mailto:"+g.dataset.contact+(body?"?body="+encodeURIComponent(body):"");return}location.href=g.dataset.go+":"+g.dataset.contact;return}let dt=e.target.closest('[data-action="door-toggle"]');if(dt){let card=dt.closest(".doorCard"),closed=card.classList.toggle("collapsed"),n=card.querySelectorAll(".doorVoter").length;dt.textContent=(closed?"▸ ":"▾ ")+n+" voter"+(n===1?"":"s");return}let dk=e.target.closest('[data-action="door-knock"]');if(dk){let ids=dk.dataset.voters.split(",").filter(Boolean),value=!dk.classList.contains("on");try{await Promise.all(ids.map(id=>setv(id,"knock_lit",value)));dk.classList.toggle("on",value);dk.textContent=value?"✅":"☑️";dk.closest(".doorCard")?.classList.toggle("doorKnocked",value)}catch(err){alert(err.message)}return}let n=e.target.closest('[data-action="note"]');if(n){let w=document.querySelector('[data-note-wrap="'+CSS.escape(n.dataset.voter)+'"]');if(w){w.classList.toggle("open");if(w.classList.contains("open"))w.querySelector(".note")?.focus()}return}let a=e.target.closest('[data-action="toggle"]');if(a){await toggle(a,a.dataset.voter,a.dataset.field);return}let fs=e.target.closest("[data-fieldkey]");if(fs){await setFieldSort(fs);return}let sr=e.target.closest("[data-open-street]");if(sr){$("#street").value=sr.dataset.openStreet;let cb=document.querySelector('.tabs button[data-tab="canvass"]');switchTab("canvass",cb);return}});
document.addEventListener("change",e=>{if(e.target.matches(".note"))setv(e.target.dataset.voter,"notes",e.target.value);if(e.target.matches("[data-cal-note]"))fetch("/api/calendar/notes",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({event_id:Number(e.target.dataset.calNote),notes:e.target.value})})});
async function login(){let r=await fetch("/api/login",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name:$("#loginName").value,pin:$("#loginPin").value})}),z=await r.json();if(!r.ok){$("#loginError").textContent=z.error||"Sign in failed";return}location.reload()}$("#loginBtn").addEventListener("click",login);$("#loginPin").addEventListener("keydown",e=>{if(e.key==="Enter")login()});
